import React, { useState } from "react";
import { InvitePortalUserForm } from "./invite-portal-user-form";
import { MutationUpdaterFn } from "@apollo/client";
import { InviteUserRes } from "graphql-src/users/mutations";
import { Drawer, Result, Button } from "antd";

interface Props {
  visible: boolean;
  onClose(): void;
  companyId: string;
  update?: MutationUpdaterFn<InviteUserRes>;
}

export const InvitePortalUserDrawer = ({
  visible,
  onClose,
  companyId,
  update,
}: Props) => {
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState(false);

  const onSuccess = () => {
    setSuccess(true);
  };

  const onError = () => {
    setError(true);
  };

  const handleClose = () => {
    setSuccess(false);
    setError(false);
    onClose();
  };

  const handleAddAnother = () => {
    setSuccess(false)
  }

  return (
    <Drawer
      title="Invite New User"
      placement="right"
      closable={false}
      onClose={handleClose}
      visible={visible}
      width={500}
    >
      {visible && success ? (
        <Result
          status="success"
          title="User has been successfully invited!"
          extra={[
            <Button type="primary" key="console" onClick={handleClose}>
              Go Back
            </Button>,
            <Button type="default" key="console" onClick={handleAddAnother}>
              Add Another User
            </Button>,
          ]}
        />
      ) : error ? (
        <Result
          status="error"
          title="An error has occurred!"
          subTitle="This error has been reported to our team."
          extra={[
            <Button type="primary" danger key="console" onClick={handleClose}>
              Go Back
            </Button>,
          ]}
        />
      ) : (
        <InvitePortalUserForm
          companyId={companyId}
          onClose={onClose}
          update={update}
          onSuccess={onSuccess}
          onError={onError}
        />
      )}
    </Drawer>
  );
};
