import { gql } from '@apollo/client'
import { Roles } from 'types'

export const InviteUser = gql`
  mutation inviteUser(
    $email: String!
    $name: String!
    $companyId: String!
    $role: Role!
  ) {
    inviteUser(
      data: {
        email: $email
        name: $name
        role: $role
        company: {
          id: $companyId
        }
      }
    ) {
        id
        name
        email
        emailVerified
        companies {
          id
          role
        }
    }
  }
`

export interface InviteUserArgs {
  email: string;
  name: string;
  companyId: string;
  role: Roles;
}

export interface InviteUserRes {
  inviteUser: {
    id: string;
    name: string;
    email: string;
    emailVerified: boolean;
    companies: [{
      id: string;
      role: Roles;
    }]
  }
}