import { gql } from '@apollo/client'
import { Roles } from 'types'

export const EditUser = gql`
  mutation updateOneUser(
    $id: String!
    $email: String!
    $name: String!
    $companyId: String!
    $role: Role!
  ) {
    updateOneUser(
      where: { id: $id }
      data: {
        email: { set: $email }
        name: { set: $name }
        companies: {
          update: {
            where: {
              id: $companyId
            }
            data: {
              role: { set: $role }
            }
          }
        }
      }
    ) {
        id
        name
        email
        companies {
          id
          role
        }
    }
  }
`

export interface EditUserArgs {
  id: string;
  email: string;
  name: string;
  companyId: string;
  role: Roles
}

export interface EditUserRes {
  user: {
    id: string;
    name: string;
    email: string;
    companies: {
      id: string;
      role: string;
    }[]
  }
}