
import React, { useState } from "react";
import { Table, Button, Row, Col, Typography, Dropdown, Menu, Modal } from "antd";
import { PlusOutlined, DeleteOutlined, MoreOutlined, EditOutlined, ExclamationCircleOutlined } from "@ant-design/icons";
import { useQuery, useMutation } from '@apollo/client'
import { CompanyUsers, CompanyUsersArgs, CompanyUsersRes } from 'graphql-src/users/queries'
import { DeleteUser, DeleteUserArgs, DeleteUserRes } from 'graphql-src/users/mutations'

import { InvitePortalUserDrawer, EditPortalUserDrawer } from 'components/form-components/portal-user'
import { useStoreState } from 'state'
import { Roles } from "types";

const { Title } = Typography
const { confirm } = Modal;

interface PortalUserItem {
  key: React.Key;
  name: string;
  email: string;
  role: string;
}

export const PortalUsersList = () => {
  const currentCompany = useStoreState(state => state.user.currentCompany)
  const currentUser = useStoreState(state => state.user.id)

  const [addVisible, setAddVisible] = useState(false)
  const [editVisible, setEditVisible] = useState('')
  // const [selected, setSelect] = useState<PortalUserItem[]>([])

  const [deleteUser] = useMutation<DeleteUserRes, DeleteUserArgs>(DeleteUser, {
    update(cache, { data }) {
      console.log(data)
      const cacheData = cache.readQuery<CompanyUsersRes, CompanyUsersArgs>({
        query: CompanyUsers,
        variables: {
          companyId: currentCompany?.company.id!,
        }
      })

      cache.writeQuery<CompanyUsersRes, CompanyUsersArgs>({
        query: CompanyUsers,
        variables: {
          companyId: currentCompany?.company.id!,
        },
        data: {
          users: cacheData?.users.filter(({ id }) => id !== data?.deleteOneUser.id)!
        }
      })
    }
  })

  const handleDelete = (id: string) => {
    confirm({
      title: 'Are you sure you want to remove this user?',
      icon: <ExclamationCircleOutlined />,
      content: 'They will be permanently removed from your company, this cannot be undone.',
      onOk() {
        deleteUser({
          variables: {
            company: currentCompany?.company.id!,
            user: id
          },
          optimisticResponse: {
            deleteOneUser: {
              id
            }
          }
        })
      },
      onCancel() {
        console.log('Cancel');
      },
      okButtonProps: { danger: true }
    });
    
  }

  const columns = [
    {
      title: "Name",
      dataIndex: "name",
      key: "name",
    },
    {
      title: "Role",
      dataIndex: "role",
      key: "role",
    },
    {
      title: "Email",
      dataIndex: "email",
      key: "email",
    },
    {
      title: "",
      key: "actions",
      dataIndex: 'key',
      render: (id: string) => <Dropdown disabled={currentUser === id} overlay={<Menu>
        <Menu.Item icon={<EditOutlined />} onClick={() => setEditVisible(id)}>
          Edit User
        </Menu.Item>
        <Menu.Item danger icon={<DeleteOutlined />} onClick={() => handleDelete(id)}>
          Remove User
        </Menu.Item>
      </Menu>}>
      <Button shape="circle" type="text">
        <MoreOutlined style={{ fontSize: 20 }} />
      </Button>
    </Dropdown>,
    }
  ];

  const rowSelection = {
    onChange: (_: React.Key[], selectedRows: PortalUserItem[]) => {
      // setSelect(selectedRows)
      console.log(selectedRows)
    },
    getCheckboxProps: (record: PortalUserItem) => ({
      disabled: record.name === 'Disabled User', // Column configuration not to be checked
      name: record.name,
    }),
  };

  const { data, loading } = useQuery<CompanyUsersRes, CompanyUsersArgs>(CompanyUsers, {
    variables: {
      companyId: currentCompany?.company.id!
    }
  })

  return (
    <div>
      <Row align="middle" style={{ marginBottom: 15 }}>
        <Title level={3} style={{ marginBottom: 0 }}>Portal Users</Title>
        <Col flex={1} />
        {/* {selected.length > 0 && <Button
          type="default"
          icon={<DeleteOutlined />}
          onClick={() => alert(selected)}
          style={{ marginRight: 10 }}
          danger
        >Remove Users</Button>} */}
        <Button
          type="primary"
          icon={<PlusOutlined />}
          onClick={() => setAddVisible(true)}
        >Invite User</Button>
      </Row>
      <Table
        columns={columns}
        dataSource={data ? data.users.map(({ id, name, email, companies }) => ({
          key: id,
          name,
          email,
          role: companies[0].role === Roles.admin ? 'Admin' : 'User'
        })) : []}
        loading={loading}
        rowSelection={{
          type: 'checkbox',
          ...rowSelection,
        }}
      />

      <InvitePortalUserDrawer
        visible={addVisible}
        onClose={() => setAddVisible(false)}
        companyId={currentCompany?.company.id!}
        update={(cache, { data }) => {
          const cacheData = cache.readQuery<CompanyUsersRes, CompanyUsersArgs>({
            query: CompanyUsers,
            variables: {
              companyId: currentCompany?.company.id!,
            }
          })

          cache.writeQuery<CompanyUsersRes, CompanyUsersArgs>({
            query: CompanyUsers,
            variables: {
              companyId: currentCompany?.company.id!,
            },
            data: {
              users: [...cacheData?.users!, {
                companies: data?.inviteUser.companies!,
                email: data?.inviteUser.email!,
                id: data?.inviteUser.id!,
                name: data?.inviteUser.name!
              }]
            }
          })
        }}
      />

      <EditPortalUserDrawer
        visible={!!editVisible}
        userId={editVisible}
        onClose={() => setEditVisible('')}
        companyId={currentCompany?.company.id!}
      />
    </div>
  );
};
