import { gql } from "@apollo/client";
import { Roles } from "types";

export const EditUser = gql`
  query user($id: String! $companyId: String!) {
    user(
      where: {
        id: $id
      }
    ) {
      id
      name
      email
      companies(where: { company: { id: { equals: $companyId } } }) {
        id
        role
      }
    }
  }
`;
export interface EditUserArgs {
  id: string;
  companyId: string;
}

export interface EditUserRes {
  user: {
    id: string;
    name: string;
    email: string;
    companies: {
      id: string;
      role: Roles;
    }[]
  };
}
