import React from "react";
import { useMutation, useQuery } from "@apollo/client";
import {
  EditUser,
  EditUserArgs,
  EditUserRes,
} from "graphql-src/users/mutations";
import {
  EditUser as Query,
  EditUserArgs as QueryArgs,
  EditUserRes as QueryRes,
} from "graphql-src/users/queries";

import { PortalUserForm, PortalUserFormData } from "../portal-user-form";

interface Props {
  onClose(): void;
  onSuccess(data: EditUserRes): void;
  onError?(): void;
  companyId: string;
  userId: string;
}

export const EditPortalUserForm = ({
  onClose,
  companyId,
  onSuccess,
  userId,
  onError
}: Props) => {
  const { data } = useQuery<QueryRes, QueryArgs>(Query, {
    variables: {
      id: userId,
      companyId
    },
    skip: !userId
  });

  const [editUser, { loading: saving }] = useMutation<
    EditUserRes,
    EditUserArgs
  >(EditUser, {
    onCompleted: (data) => {
      onSuccess(data);
    },
    onError: () => {
      onError && onError()
    }
  });

  const handleSubmit = async ({ name, email, role }: PortalUserFormData) => {
    await editUser({
      variables: {
        id: userId,
        name,
        email,
        companyId: data?.user.companies[0].id!,
        role,
      },
      optimisticResponse: {
        user: {
          email,
          name: name,
          id: `${Math.random()}`,
          companies: [{
            id: companyId,
            role,
          }],
        },
      },
    });
  };

  return (
    <PortalUserForm
      saving={saving}
      onClose={onClose}
      onSubmit={handleSubmit}
      data={data && data.user ? {
        name: data.user.name,
        email: data.user.email,
        role: data.user.companies[0].role
      } : undefined}
      loading={!data}
    />
  );
};
