import { gql } from '@apollo/client'

export const UserState  = gql`
  query user(
    $id: String!
  ) {
    user(
      where: { id: $id }
    ) {
      id
      demGroups {
        id
        name
        evidenceCount
      }
      companies {
        id
        role
        company {
          id
          name
        }
      }
    }
  }
`


export interface UserStateRes {
  user: {
    id: string;
    demGroups: {
      id: string;
      name: string;
      evidenceCount: number;
    }[]
    companies: {
      id: string;
      role: string;
      company: {
        id: string;
        name: string;
      }
    }[]
  }
}