import { gql } from "@apollo/client";
import { Roles } from "types";

export const CompanyUsers = gql`
  query users($companyId: String!) {
    users(
      where: {
        recycled: { equals: false },
        companies: { some: { recycled: { equals: false }, company: { id: { equals: $companyId } } } }
      }
    ) {
      id
      name
      email
      companies(where: { company: { id: { equals: $companyId } } }) {
        id
        role
      }
    }
  }
`;
export interface CompanyUsersArgs {
  companyId: string;
}

export interface CompanyUsersRes {
  users: {
    id: string;
    name: string;
    email: string;
    companies: {
      id: string;
      role: Roles;
    }[];
  }[];
}
