import React from "react";
import { useMutation, MutationUpdaterFn } from "@apollo/client";
import {
  InviteUserArgs,
  InviteUserRes,
  InviteUser,
} from "graphql-src/users/mutations";

import { PortalUserForm, PortalUserFormData } from "../portal-user-form";

interface Props {
  onClose(): void;
  companyId: string;
  update?: MutationUpdaterFn<InviteUserRes>;
  onSuccess?(): void;
  onError?(): void;
}

export const InvitePortalUserForm = ({
  onClose,
  companyId,
  update,
  onError,
  onSuccess,
}: Props) => {
  const [inviteUser, { loading }] = useMutation<InviteUserRes, InviteUserArgs>(
    InviteUser,
    {
      update,
      onCompleted: onSuccess,
      onError,
    }
  );

  const handleSubmit = async ({ name, email, role }: PortalUserFormData) => {
    await inviteUser({
      variables: {
        name,
        email,
        companyId,
        role,
      },
      optimisticResponse: {
        inviteUser: {
          email,
          emailVerified: false,
          name: name,
          id: `${Math.random()}`,
          companies: [
            {
              id: companyId,
              role,
            },
          ],
        },
      },
    });
  };

  return (
    <PortalUserForm
      saving={loading}
      onClose={onClose}
      onSubmit={handleSubmit}
    />
  );
};
