import { gql } from '@apollo/client'

export const DeleteUser = gql`
  mutation deleteOneUser(
    $user: String!
    $company: String!
  ) {
    deleteOneUser(
      user: { id: $user }
      company: { id: $company }
    ) {
      id
    }
  }
`

export interface DeleteUserArgs {
  user: string;
  company: string;
}

export interface DeleteUserRes {
  deleteOneUser: {
    id: string;
  }
}