import React, { useRef, useEffect } from "react";
import { Form, Input, Button, FormInstance, Row, Select } from "antd";
import { Roles } from "types";

const { Option } = Select

export interface PortalUserFormData {
  name: string;
  email: string;
  role: Roles
}

interface Props {
  onClose(): void;
  onSubmit(data: PortalUserFormData): void;
  loading?: boolean;
  saving: boolean;
  data?: PortalUserFormData|undefined;
}

export const PortalUserForm = ({ onClose, onSubmit, loading, saving, data }: Props) => {
  const formRef = useRef<FormInstance<PortalUserFormData>>(null);

  useEffect(() => {
    if (data) {
      formRef.current?.setFieldsValue({
        name: data.name,
        email: data.email,
        role: data.role
      })
    }
  }, [data])

  const layout = {
    labelCol: { span: 6 },
    wrapperCol: { span: 16 },
  };

  const tailLayout = {
    wrapperCol: { span: 22 },
  };

  const handleClose = () => {
    formRef.current?.resetFields();
    onClose();
  };

  const handleSubmit = async (data: PortalUserFormData) => {
    onSubmit(data)
  };

  return (
    <Form
      {...layout}
      name="basic"
      onFinish={handleSubmit}
      onFinishFailed={() => {}}
      ref={formRef}
      initialValues={{
        name: '',
        email: '',
        role: Roles.user
      }}
    >
      <Form.Item
        label="Full Name"
        name="name"
        rules={[{ required: true, message: "Please input their full name." }]}
      >
        <Input disabled={loading || saving} />
      </Form.Item>

      <Form.Item
        label="Email Address"
        name="email"
        rules={[
          { required: true, message: "Please input their email address." },
          { type: "email", message: "Please enter a valid email address." },
        ]}
      >
        <Input disabled={loading || saving} />
      </Form.Item>

      <Form.Item
        label="Role"
        name="role"
        rules={[
          { required: true, message: "Please input their email address." },
        ]}
      >
        <Select defaultValue={Roles.user} disabled={loading || saving}>
          <Option value={Roles.user}>User</Option>
          <Option value={Roles.admin}>Admin</Option>
        </Select>
      </Form.Item>

      <Form.Item {...tailLayout}>
        <Row justify="end">
          <Button
            type="ghost"
            onClick={handleClose}
            style={{ marginRight: 15 }}
            disabled={loading || saving}
          >
            Cancel
          </Button>
          <Button type="primary" htmlType="submit" loading={saving} disabled={loading}>
            Submit
          </Button>
        </Row>
      </Form.Item>
    </Form>
  );
};
