import React, { useState } from "react";
import { Drawer, Result, Button } from "antd";
import { EditPortalUserForm } from "./edit-portal-user-form";

interface Props {
  visible: boolean;
  onClose(): void;
  companyId: string;
  userId: string;
}

export const EditPortalUserDrawer = ({
  visible,
  onClose,
  companyId,
  userId
}: Props) => {
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState(false);

  const onSuccess = () => {
    setSuccess(true);
  };

  const onError = () => {
    setError(true);
  };

  const handleClose = () => {
    setSuccess(false)
    setError(false)
    onClose()
  }

  return (
    <Drawer
      title="Invite New User"
      placement="right"
      closable={false}
      onClose={onClose}
      visible={visible}
      width={500}
    >
      {visible && success ? (
        <Result
          status="success"
          title="User has been successfully updated!"
          extra={[
            <Button type="primary" key="console" onClick={handleClose}>
              Go Back
            </Button>,
          ]}
        />
      ) : error ? (
        <Result
          status="error"
          title="An error has occurred!"
          subTitle="This error has been reported to our team."
          extra={[
            <Button type="primary" danger key="console" onClick={handleClose}>
              Go Back
            </Button>,
          ]}
        />
      ) : (
        <EditPortalUserForm
          companyId={companyId}
          onClose={onClose}
          onSuccess={onSuccess}
          userId={userId}
          onError={onError}
        />
      )}
    </Drawer>
  );
};
